text(await tools.exec_command({workdir:load("w"),cmd:`$env:TEMP=$PWD.Path
$env:TMP=$PWD.Path
$cycles = @(Get-ChildItem -LiteralPath selftest-audit -File -Filter 'cycle-*.json' | Sort-Object Name | ForEach-Object {
    Get-Content -LiteralPath $_.FullName -Raw -Encoding utf8 | ConvertFrom-Json
})
$sourceHash = (Get-FileHash -LiteralPath main.lfz).Hash
$commands = [Collections.Generic.List[object]]::new()
foreach ($cycle in $cycles) {
    if ($cycle.source_hashes.'main.lfz' -ne $sourceHash -or $cycle.runs.Count -ne 2 -or $cycle.runs[0].exit -ne 0) {
        throw "Invalid check/run evidence"
    }
    foreach ($run in $cycle.runs) {
        $commands.Add([string[]]$run.args)
    }
}
$mixed = $cycles[0].runs[1].stdout | ConvertFrom-Json
$budget = $cycles[1].runs[1]
$empty = $cycles[2].runs[1].stdout | ConvertFrom-Json
$edges = $cycles[3].runs[1].stdout | ConvertFrom-Json
if ($cycles.Count -ne 4 -or $mixed.count -ne 8 -or !$mixed.nilOk -or $mixed.items[0].value -ne 1 -or $mixed.items[1].value -ne -2 -or
    @($mixed.items[2..7] | Where-Object { !$_.ok -and $null -eq $_.value -and $_.error -eq 'AssertionError' }).Count -ne 6 -or
    $budget.exit -ne 2 -or $budget.stdout -ne '' -or $budget.stderr -notmatch 'ExecutionLimitError' -or
    $empty.count -ne 0 -or $empty.items.Count -ne 0 -or !$empty.nilOk -or
    $edges.items[0].value -ne [long]::MinValue -or $edges.items[1].value -ne [long]::MaxValue -or $edges.items[2].error -ne 'AssertionError' -or $edges.items[3].value -ne 0) {
    throw 'Self-test result mismatch'
}
ConvertTo-Json -InputObject $commands.ToArray() -Depth 4 | Set-Content -LiteralPath commands.json -Encoding utf8NoBOM
$savedCommands = Get-Content -Raw -Encoding utf8 commands.json | ConvertFrom-Json -NoEnumerate
if ($savedCommands.Count -ne $commands.Count -or (Compare-Object (ConvertTo-Json -InputObject $savedCommands -Compress) (ConvertTo-Json -InputObject $commands.ToArray() -Compress))) {
    throw 'Command record mismatch'
}
'Verified four cycles and eight recorded argv arrays.'`}))

